import React from 'react';
import { useNavigate } from 'react-router-dom';
import { createPageUrl } from '@/lib/utils';
import traceLogo from '@/images/trace.png';

export default function Welcome() {
  const navigate = useNavigate();

  return (
    <div className="min-h-screen bg-[#FAFAF8] flex flex-col items-center justify-center p-4">
      {/* Header - Fixed positioning */}
      <header className="sticky top-0 left-0 right-0 bg-[#FAFAF8]/95 backdrop-blur-sm border-b border-slate-200 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="text-center">
              <img 
                src={traceLogo}
                alt="TRACE Logo" 
                className="w-12 h-12"
              />
              <h1 className="text-4xl font-bold text-[#5C6B5E] mb-2">TRACE</h1>
              <p className="text-sm text-slate-600">Your thoughts, examined</p>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="px-6">
        {/* Hero Section */}
        <section className="pt-12 pb-16 text-center">
          <p className="text-[#1E1E1E]/70 leading-relaxed mb-12 max-w-xs mx-auto">
            Explore and understand your thoughts. Record what you believe, why you believe it, and how your thinking evolves over time. A private space for reflection and clarity.
          </p>

          <button
            onClick={() => navigate(createPageUrl('NewThought'))}
            className="inline-flex items-center gap-2 px-8 py-3.5 border border-[#1E1E1E] rounded-lg text-[#1E1E1E] text-sm tracking-wide hover:bg-[#1E1E1E] hover:text-[#FAFAF8] transition-colors"
          >
            <span className="text-lg font-light">+</span>
            <span>New Thought</span>
          </button>
        </section>


      </main>

      {/* Bottom Spacing */}
      <div className="h-20" />
    </div>
  );
}
